WITH nd AS (SELECT sc.SEC_SNAME, fin.F110101 FROM VIEW_STK_FIN_IDX fin INNER JOIN GET_A_SEC_CODE sc ON fin.COMCODE = sc.COMCODE WHERE sc.SEC_SNAME LIKE '%宁德时代%' AND fin.ENDDATE = '2025-12-31 00:00:00' AND fin.F110101 IS NOT NULL AND fin.ISVALID = 1 AND sc.ISVALID = 1 ORDER BY fin.ENDDATE DESC LIMIT 1), zb AS (SELECT sc.SEC_SNAME, fin.F110101 FROM VIEW_STK_FIN_IDX fin INNER JOIN GET_A_SEC_CODE sc ON fin.COMCODE = sc.COMCODE WHERE sc.SEC_SNAME LIKE '%招商银行%' AND fin.ENDDATE = '2025-12-31 00:00:00' AND fin.F110101 IS NOT NULL AND fin.ISVALID = 1 AND sc.ISVALID = 1 ORDER BY fin.ENDDATE DESC LIMIT 1) SELECT nd.SEC_SNAME AS `公司一`, ROUND(nd.F110101 / 10000, 1) AS `归母净利润一(万)`, zb.SEC_SNAME AS `公司二`, ROUND(zb.F110101 / 10000, 1) AS `归母净利润二(万)`, CASE WHEN nd.F110101 > zb.F110101 THEN nd.SEC_SNAME WHEN nd.F110101 < zb.F110101 THEN zb.SEC_SNAME ELSE '相等' END AS `利润更高者`, ROUND(ABS(nd.F110101 - zb.F110101) / 10000, 1) AS `高出金额(万)` FROM nd CROSS JOIN zb;
